    const a0 = await etat(pa), b0 = await etat(pb), c0 = await etat(pc), g0 = await globaux();
    await commande('CMD139A', [{ code: pa, quantite: 5, prix: 120 }, { code: pb, quantite: 3, prix: 200 }, { code: pc, quantite: 2, prix: 55 }]);
