    const lot1 = await B.appliquer('natures-facture', [E, [NA, 'Sonde B2 Orthopédie ' + sfx, 'Chirurgie', 'Décision test'], [NB, 'Sonde B2 Pédiatrie ' + sfx, 'Maternité', '']]);
