        a18: (SE.enVigueur('VAR-NFS-GB', '2026-08-18') || {}).version, a19: (SE.enVigueur('VAR-NFS-GB', '2026-08-19') || {}).version, a20: (SE.enVigueur('VAR-NFS-GB', '2026-08-20') || {}).version, a25: (SE.enVigueur('VAR-NFS-GB', '2026-08-25') || {}).version,
