      const cX = 'TF196X' + suf;
      PR.proposerTarif({ code: cX, prixNonAssure: 3100, etatAssure: 'unique', dateEffet: jour, motif: 'Sonde 196', creation: { libelle: 'Acte sonde 196', famille: 'ACTE', secteur: 'Soins' } });
